'use client';

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { X, ChevronLeft, ChevronRight, Info, Check, ShieldCheck } from 'lucide-react';
import clsx from 'clsx';

export interface ClassOption {
  code: string;
  name: string;
}

const DEFAULT_TRAIN_CLASSES: ClassOption[] = [
  { code: 'SL', name: 'Sleeper' },
  { code: '3A', name: 'Third AC' },
  { code: 'HA', name: 'First AC & Second AC' },
  { code: '2A', name: 'Second AC' },
  { code: 'CC', name: 'AC Chair Car' },
  { code: '2S', name: 'Second Sitting' }
];

interface SeatMapModalProps {
  isOpen: boolean;
  onClose: () => void;
  coach?: string;
  berthNumber?: string | number;
  berthType?: string;
  passengerName?: string;
  travelClass?: string;
  trainNo?: string;
  trainName?: string;
  coachPosition?: number;
}

interface Berth {
  number: number;
  type: string; // LB, MB, UB, SL, SU, SM, W, M, A
  typeLabel: string;
  isSide?: boolean;
}

interface Bay {
  bayIndex: number;
  mainLeft: Berth[];
  mainRight: Berth[];
  sideBerths: Berth[];
}

export function SeatMapModal({
  isOpen,
  onClose,
  coach = 'S6',
  berthNumber,
  berthType,
  passengerName,
  travelClass = 'SL',
  trainNo,
  trainName,
  coachPosition = 9
}: SeatMapModalProps) {
  // Prevent background scroll
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  // Initial class resolution
  const initialClassCode = (() => {
    const c = (travelClass || '').toUpperCase();
    if (['SL', '3A', '2A', '1A', 'HA', 'CC', '2S', '3E'].includes(c)) return c;
    if (coach) {
      const co = coach.toUpperCase();
      if (co.startsWith('S') && !co.startsWith('SLR')) return 'SL';
      if (co.startsWith('B')) return '3A';
      if (co.startsWith('A')) return '2A';
      if (co.startsWith('H')) return 'HA';
      if (co.startsWith('C')) return 'CC';
      if (co.startsWith('D')) return '2S';
      if (co.startsWith('M')) return '3E';
    }
    return 'SL';
  })();

  const [selectedClass, setSelectedClass] = useState<string>(initialClassCode);
  const [coachVariant, setCoachVariant] = useState<'ICF' | 'LHB'>('ICF');
  const [previewSeat, setPreviewSeat] = useState<number | null>(null);

  const cleanUserBerth = berthNumber ? Number(berthNumber) : null;
  const layoutScrollRef = useRef<HTMLDivElement>(null);
  const userBerthRef = useRef<HTMLButtonElement>(null);

  // Sync initial class when modal opens
  useEffect(() => {
    if (isOpen) {
      setSelectedClass(initialClassCode);
      setPreviewSeat(cleanUserBerth);
    }
  }, [isOpen, initialClassCode, cleanUserBerth]);

  // Scroll to user's berth when opened
  useEffect(() => {
    if (isOpen && userBerthRef.current) {
      setTimeout(() => {
        userBerthRef.current?.scrollIntoView({
          behavior: 'smooth',
          inline: 'center',
          block: 'nearest'
        });
      }, 250);
    }
  }, [isOpen, selectedClass, coachVariant]);

  // Compute Layout bays based on class and coach variant
  const bays: Bay[] = useMemo(() => {
    const list: Bay[] = [];
    const cls = selectedClass.toUpperCase();

    if (cls === 'SL' || cls === '3A') {
      // 8 berths per bay: 6 main (2 cols of 3), 2 side (1 col of 2)
      // ICF: 72 berths (9 bays). LHB: 80 berths (10 bays).
      const totalBays = coachVariant === 'LHB' ? 10 : 9;
      let curr = 1;

      for (let b = 1; b <= totalBays; b++) {
        const ml: Berth[] = [
          { number: curr, type: 'LB', typeLabel: 'Lower Berth' },
          { number: curr + 1, type: 'MB', typeLabel: 'Middle Berth' },
          { number: curr + 2, type: 'UB', typeLabel: 'Upper Berth' }
        ];
        const mr: Berth[] = [
          { number: curr + 3, type: 'LB', typeLabel: 'Lower Berth' },
          { number: curr + 4, type: 'MB', typeLabel: 'Middle Berth' },
          { number: curr + 5, type: 'UB', typeLabel: 'Upper Berth' }
        ];
        const side: Berth[] = [
          { number: curr + 6, type: 'SL', typeLabel: 'Side Lower', isSide: true },
          { number: curr + 7, type: 'SU', typeLabel: 'Side Upper', isSide: true }
        ];

        list.push({
          bayIndex: b,
          mainLeft: ml,
          mainRight: mr,
          sideBerths: side
        });
        curr += 8;
      }
    } else if (cls === '2A' || cls === 'HA') {
      // 6 berths per bay: 4 main (2 cols of 2), 2 side
      // ICF: 46/48 berths (8 bays). LHB: 54 berths (9 bays).
      const totalBays = coachVariant === 'LHB' ? 9 : 8;
      let curr = 1;

      for (let b = 1; b <= totalBays; b++) {
        const ml: Berth[] = [
          { number: curr, type: 'LB', typeLabel: 'Lower Berth' },
          { number: curr + 1, type: 'UB', typeLabel: 'Upper Berth' }
        ];
        const mr: Berth[] = [
          { number: curr + 2, type: 'LB', typeLabel: 'Lower Berth' },
          { number: curr + 3, type: 'UB', typeLabel: 'Upper Berth' }
        ];
        const side: Berth[] = [
          { number: curr + 4, type: 'SL', typeLabel: 'Side Lower', isSide: true },
          { number: curr + 5, type: 'SU', typeLabel: 'Side Upper', isSide: true }
        ];

        list.push({
          bayIndex: b,
          mainLeft: ml,
          mainRight: mr,
          sideBerths: side
        });
        curr += 6;
      }
    } else if (cls === '3E') {
      // 3 AC Economy (83 berths with Side Middle)
      const totalBays = 9;
      let curr = 1;
      for (let b = 1; b <= totalBays; b++) {
        const ml: Berth[] = [
          { number: curr, type: 'LB', typeLabel: 'Lower Berth' },
          { number: curr + 1, type: 'MB', typeLabel: 'Middle Berth' },
          { number: curr + 2, type: 'UB', typeLabel: 'Upper Berth' }
        ];
        const mr: Berth[] = [
          { number: curr + 3, type: 'LB', typeLabel: 'Lower Berth' },
          { number: curr + 4, type: 'MB', typeLabel: 'Middle Berth' },
          { number: curr + 5, type: 'UB', typeLabel: 'Upper Berth' }
        ];
        const side: Berth[] = [
          { number: curr + 6, type: 'SL', typeLabel: 'Side Lower', isSide: true },
          { number: curr + 7, type: 'SM', typeLabel: 'Side Middle', isSide: true },
          { number: curr + 8, type: 'SU', typeLabel: 'Side Upper', isSide: true }
        ];
        list.push({ bayIndex: b, mainLeft: ml, mainRight: mr, sideBerths: side });
        curr += 9;
      }
    } else {
      // Chair Car or Second Sitting (3 + 2 layout)
      const totalRows = coachVariant === 'LHB' ? 16 : 14;
      let curr = 1;
      for (let r = 1; r <= totalRows; r++) {
        const ml: Berth[] = [
          { number: curr, type: 'W', typeLabel: 'Window' },
          { number: curr + 1, type: 'M', typeLabel: 'Middle' },
          { number: curr + 2, type: 'A', typeLabel: 'Aisle' }
        ];
        const mr: Berth[] = [
          { number: curr + 3, type: 'A', typeLabel: 'Aisle' },
          { number: curr + 4, type: 'W', typeLabel: 'Window' }
        ];
        list.push({ bayIndex: r, mainLeft: ml, mainRight: mr, sideBerths: [] });
        curr += 5;
      }
    }

    return list;
  }, [selectedClass, coachVariant]);

  const handleScroll = (dir: 'left' | 'right') => {
    if (!layoutScrollRef.current) return;
    const delta = dir === 'left' ? -320 : 320;
    layoutScrollRef.current.scrollBy({ left: delta, behavior: 'smooth' });
  };

  if (!isOpen) return null;

  const currentClassName =
    DEFAULT_TRAIN_CLASSES.find(c => c.code === selectedClass)?.name || selectedClass;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 md:p-6 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div
        className="relative w-full max-w-3xl max-h-[92vh] overflow-y-auto rounded-[2.5rem] border border-subtle bg-card shadow-2xl space-y-6 text-main"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Top Header */}
        <div className="sticky top-0 z-30 bg-card/95 backdrop-blur-md border-b border-subtle/80 px-6 md:px-8 py-5 flex items-start justify-between">
          <div>
            <h2 className="text-xl md:text-2xl font-black text-main tracking-tight">
              Seat / Berth Layout
            </h2>
            <p className="text-xs text-muted font-medium mt-0.5">
              {coach} · {currentClassName} · position {coachPosition}
            </p>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="h-10 w-10 rounded-2xl bg-input border border-subtle grid place-items-center text-muted hover:text-main hover:bg-subtle/40 transition-colors shadow-sm"
            aria-label="Close modal"
          >
            <X size={18} />
          </button>
        </div>

        {/* Modal Body */}
        <div className="px-6 md:px-8 space-y-7 pb-6">
          {/* Section 1: Classes on this train */}
          <div className="space-y-3">
            <h3 className="text-sm font-black text-main tracking-tight">
              Classes on this train
            </h3>

            <div className="rounded-3xl border border-subtle bg-input/20 overflow-hidden divide-y divide-subtle/60">
              {DEFAULT_TRAIN_CLASSES.map((cls) => {
                const isSelected = selectedClass === cls.code;
                return (
                  <button
                    key={cls.code}
                    type="button"
                    onClick={() => {
                      setSelectedClass(cls.code);
                    }}
                    className={clsx(
                      "w-full flex items-center gap-3.5 px-4 py-3 text-left transition-colors",
                      isSelected
                        ? "bg-blue-500/10 dark:bg-blue-500/20 text-primary font-bold"
                        : "hover:bg-subtle/30 text-main"
                    )}
                  >
                    {/* Circle Class Badge */}
                    <div
                      className={clsx(
                        "h-8 w-8 rounded-full grid place-items-center text-xs font-black shadow-sm",
                        isSelected
                          ? "bg-blue-600 text-white"
                          : "bg-blue-600 text-white"
                      )}
                    >
                      {cls.code}
                    </div>

                    <span className="text-sm font-bold flex-1">
                      {cls.name}
                    </span>

                    {isSelected && (
                      <span className="text-xs font-bold text-primary px-2.5 py-0.5 rounded-full bg-primary/10 border border-primary/20">
                        Active
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Section 2: Seat / Berth Layout Graphic Box */}
          <div className="rounded-3xl border border-subtle overflow-hidden bg-card shadow-md space-y-4">
            {/* Blue Banner Header */}
            <div className="bg-blue-600 text-white px-5 py-3 font-black text-xs md:text-sm tracking-wider uppercase flex items-center justify-between">
              <span>{currentClassName} · SEAT / BERTH LAYOUT</span>
              <span className="text-[10px] opacity-80 lowercase font-normal">
                {coachVariant} model
              </span>
            </div>

            {/* Coach Type Toggle Buttons */}
            <div className="px-5 pt-1 flex items-center gap-2.5">
              <button
                type="button"
                onClick={() => setCoachVariant('ICF')}
                className={clsx(
                  "px-4 py-1.5 rounded-xl text-xs font-bold transition-all border",
                  coachVariant === 'ICF'
                    ? "border-blue-600 bg-blue-500/10 text-blue-600 dark:text-blue-400 font-black shadow-sm"
                    : "border-subtle bg-input/40 text-muted hover:text-main"
                )}
              >
                ICF Coach
              </button>

              <button
                type="button"
                onClick={() => setCoachVariant('LHB')}
                className={clsx(
                  "px-4 py-1.5 rounded-xl text-xs font-bold transition-all border",
                  coachVariant === 'LHB'
                    ? "border-blue-600 bg-blue-500/10 text-blue-600 dark:text-blue-400 font-black shadow-sm"
                    : "border-subtle bg-input/40 text-muted hover:text-main"
                )}
              >
                LHB Coach
              </button>
            </div>

            {/* Coach Layout Display */}
            <div className="relative border-y border-subtle/80 bg-input/10 py-5 px-3">
              <div
                ref={layoutScrollRef}
                className="flex items-stretch gap-4 overflow-x-auto pb-4 no-scrollbar scroll-smooth pl-2"
              >
                {/* Left Door Bar */}
                <div className="flex-shrink-0 w-8 md:w-9 rounded-xl bg-slate-900 text-white flex items-center justify-center border border-slate-700 shadow-md select-none">
                  <span className="text-[10px] font-black uppercase tracking-widest -rotate-90 whitespace-nowrap text-slate-300">
                    DOOR
                  </span>
                </div>

                {/* Bays List */}
                {bays.map((bay) => (
                  <div
                    key={bay.bayIndex}
                    className="flex-shrink-0 flex items-stretch gap-3 pl-2 pr-3 border-r border-dashed border-subtle/80 last:border-r-0"
                  >
                    {/* Main Coupe: 2 columns */}
                    <div className="flex gap-2">
                      {/* Left Column */}
                      <div className="flex flex-col gap-2">
                        {bay.mainLeft.map((berth) => {
                          const isAllocated = cleanUserBerth === berth.number;
                          const isPreview = previewSeat === berth.number;

                          return (
                            <button
                              key={berth.number}
                              ref={isAllocated ? userBerthRef : undefined}
                              type="button"
                              onClick={() => setPreviewSeat(berth.number)}
                              className={clsx(
                                "w-11 h-11 md:w-12 md:h-12 rounded-xl flex flex-col items-center justify-center transition-all duration-150 border text-center font-black select-none",
                                isAllocated
                                  ? "bg-blue-600 text-white border-2 border-blue-400 shadow-lg shadow-blue-500/40 ring-2 ring-blue-500/50 scale-105 z-10"
                                  : isPreview
                                  ? "bg-blue-500 text-white border-blue-400 shadow-md ring-1 ring-blue-400"
                                  : "border-cyan-400/60 dark:border-cyan-700/60 bg-cyan-50/70 dark:bg-cyan-950/40 text-cyan-950 dark:text-cyan-200 hover:border-cyan-500 hover:bg-cyan-100/70 dark:hover:bg-cyan-900/40"
                              )}
                              title={`${berth.number} - ${berth.typeLabel}`}
                            >
                              <span className="text-xs md:text-sm leading-none font-black">
                                {berth.number}
                              </span>
                              <span
                                className={clsx(
                                  "text-[8px] font-bold tracking-tighter mt-0.5",
                                  isAllocated || isPreview ? "text-blue-100" : "text-cyan-700 dark:text-cyan-300"
                                )}
                              >
                                {berth.type}
                              </span>
                            </button>
                          );
                        })}
                      </div>

                      {/* Right Column */}
                      <div className="flex flex-col gap-2">
                        {bay.mainRight.map((berth) => {
                          const isAllocated = cleanUserBerth === berth.number;
                          const isPreview = previewSeat === berth.number;

                          return (
                            <button
                              key={berth.number}
                              ref={isAllocated ? userBerthRef : undefined}
                              type="button"
                              onClick={() => setPreviewSeat(berth.number)}
                              className={clsx(
                                "w-11 h-11 md:w-12 md:h-12 rounded-xl flex flex-col items-center justify-center transition-all duration-150 border text-center font-black select-none",
                                isAllocated
                                  ? "bg-blue-600 text-white border-2 border-blue-400 shadow-lg shadow-blue-500/40 ring-2 ring-blue-500/50 scale-105 z-10"
                                  : isPreview
                                  ? "bg-blue-500 text-white border-blue-400 shadow-md ring-1 ring-blue-400"
                                  : "border-cyan-400/60 dark:border-cyan-700/60 bg-cyan-50/70 dark:bg-cyan-950/40 text-cyan-950 dark:text-cyan-200 hover:border-cyan-500 hover:bg-cyan-100/70 dark:hover:bg-cyan-900/40"
                              )}
                              title={`${berth.number} - ${berth.typeLabel}`}
                            >
                              <span className="text-xs md:text-sm leading-none font-black">
                                {berth.number}
                              </span>
                              <span
                                className={clsx(
                                  "text-[8px] font-bold tracking-tighter mt-0.5",
                                  isAllocated || isPreview ? "text-blue-100" : "text-cyan-700 dark:text-cyan-300"
                                )}
                              >
                                {berth.type}
                              </span>
                            </button>
                          );
                        })}
                      </div>
                    </div>

                    {/* Aisle Spacer / Walkway */}
                    <div className="w-1 border-r border-dashed border-subtle/60 mx-1" />

                    {/* Side Berths Column */}
                    {bay.sideBerths.length > 0 && (
                      <div className="flex flex-col justify-end gap-2">
                        {bay.sideBerths.map((berth) => {
                          const isAllocated = cleanUserBerth === berth.number;
                          const isPreview = previewSeat === berth.number;

                          return (
                            <button
                              key={berth.number}
                              ref={isAllocated ? userBerthRef : undefined}
                              type="button"
                              onClick={() => setPreviewSeat(berth.number)}
                              className={clsx(
                                "w-11 h-11 md:w-12 md:h-12 rounded-xl flex flex-col items-center justify-center transition-all duration-150 border text-center font-black select-none",
                                isAllocated
                                  ? "bg-blue-600 text-white border-2 border-blue-400 shadow-lg shadow-blue-500/40 ring-2 ring-blue-500/50 scale-105 z-10"
                                  : isPreview
                                  ? "bg-blue-500 text-white border-blue-400 shadow-md ring-1 ring-blue-400"
                                  : "border-cyan-400/60 dark:border-cyan-700/60 bg-cyan-50/70 dark:bg-cyan-950/40 text-cyan-950 dark:text-cyan-200 hover:border-cyan-500 hover:bg-cyan-100/70 dark:hover:bg-cyan-900/40"
                              )}
                              title={`${berth.number} - ${berth.typeLabel}`}
                            >
                              <span className="text-xs md:text-sm leading-none font-black">
                                {berth.number}
                              </span>
                              <span
                                className={clsx(
                                  "text-[8px] font-bold tracking-tighter mt-0.5",
                                  isAllocated || isPreview ? "text-blue-100" : "text-cyan-700 dark:text-cyan-300"
                                )}
                              >
                                {berth.type}
                              </span>
                            </button>
                          );
                        })}
                      </div>
                    )}
                  </div>
                ))}
              </div>

              {/* Horizontal Scroll Controls */}
              <div className="flex items-center justify-between px-3 pt-3">
                <button
                  type="button"
                  onClick={() => handleScroll('left')}
                  className="p-1.5 rounded-lg bg-card border border-subtle text-muted hover:text-main shadow-sm"
                  aria-label="Previous bay"
                >
                  <ChevronLeft size={16} />
                </button>

                {/* Progress track */}
                <div className="flex-1 max-w-xs mx-4 h-1.5 bg-subtle/50 rounded-full overflow-hidden">
                  <div className="h-full bg-primary rounded-full w-1/3" />
                </div>

                <button
                  type="button"
                  onClick={() => handleScroll('right')}
                  className="p-1.5 rounded-lg bg-card border border-subtle text-muted hover:text-main shadow-sm"
                  aria-label="Next bay"
                >
                  <ChevronRight size={16} />
                </button>
              </div>
            </div>

            {/* Legend & Instructions */}
            <div className="px-5 pb-5 space-y-2">
              <div className="flex flex-wrap items-center gap-5 text-xs">
                <div className="flex items-center gap-2">
                  <div className="w-4 h-4 rounded bg-blue-500 shadow-sm" />
                  <span className="text-muted font-medium">Preview selection</span>
                </div>

                <div className="flex items-center gap-2">
                  <div className="w-4 h-4 rounded bg-blue-600 border-2 border-blue-400 shadow-sm" />
                  <span className="text-muted font-bold text-main">Your berth</span>
                </div>
              </div>

              <p className="text-[11px] text-muted italic">
                Tap a berth to preview its position
              </p>
            </div>
          </div>

          {/* Section 3: Bottom Disclaimer Card */}
          <div className="p-4 md:p-5 rounded-2xl bg-input/30 border border-subtle/80 text-muted text-xs leading-relaxed space-y-1">
            <p>
              Seat clicks are a layout preview only and do not change the railway booking.
              Availability colours are not live inventory. The outlined blue berth is the
              allocation returned for this PNR.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
